import{_ as a,o as t,c as i,ae as e}from"./chunks/framework.RRduUuAx.js";const q=JSON.parse('{"title":"WeChat 明細インポート","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/02-wechat-bill-import-guide.md","filePath":"v1/ja/guide/02-wechat-bill-import-guide.md"}'),o={name:"v1/ja/guide/02-wechat-bill-import-guide.md"};function r(h,l,d,n,s,u){return t(),i("div",null,[...l[0]||(l[0]=[e('<h1 id="wechat-明細インポート" tabindex="-1">WeChat 明細インポート <a class="header-anchor" href="#wechat-明細インポート" aria-label="Permalink to &quot;WeChat 明細インポート&quot;">​</a></h1><h2 id="📋-概要" tabindex="-1">📋 概要 <a class="header-anchor" href="#📋-概要" aria-label="Permalink to &quot;📋 概要&quot;">​</a></h2><p>本ガイドでは、WeChat から明細をエクスポートし、Koala にインポートする手順を説明します。</p><hr><h2 id="📱-手順-1-wechat-で明細をエクスポート" tabindex="-1">📱 手順 1：WeChat で明細をエクスポート <a class="header-anchor" href="#📱-手順-1-wechat-で明細をエクスポート" aria-label="Permalink to &quot;📱 手順 1：WeChat で明細をエクスポート&quot;">​</a></h2><h3 id="手順-1-明細-账单-画面を開く" tabindex="-1">手順 1：明細（账单）画面を開く <a class="header-anchor" href="#手順-1-明細-账单-画面を開く" aria-label="Permalink to &quot;手順 1：明細（账单）画面を開く&quot;">​</a></h3><ol><li>WeChat を開く</li><li>右下の <strong>「我」</strong> をタップ</li><li><strong>「服务」</strong>（または <strong>「支付」</strong>）をタップ</li><li>右上の <strong>「钱包」</strong> をタップ</li><li>右上の <strong>「账单」</strong> から明細画面へ</li></ol><blockquote><p>📝 注意：WeChat のバージョンにより入口が異なる場合があります。見つからない場合は、WeChat の検索で「账单」と入力して探してみてください。</p></blockquote><h3 id="手順-2-明細ファイルをダウンロード" tabindex="-1">手順 2：明細ファイルをダウンロード <a class="header-anchor" href="#手順-2-明細ファイルをダウンロード" aria-label="Permalink to &quot;手順 2：明細ファイルをダウンロード&quot;">​</a></h3><ol><li>明細画面で右上の <strong>「...」</strong> または <strong>「筛选」</strong> をタップ</li><li>下から出てくるメニューで <strong>「下载账单」</strong> をタップ</li><li><strong>「用于个人对账」</strong> を選択</li><li>受け取り方法（<strong>WeChat</strong> / <strong>メール</strong>）を選び、確定</li><li>期間（例：直近 1 か月 / 直近 3 か月など）を選び、確定</li></ol><blockquote><p>💡 ヒント：</p><ul><li>1 回のエクスポートは 3 か月以内をおすすめします（ファイルが大きいと処理が遅くなることがあります）。</li><li>長期間の履歴は複数回に分けてエクスポートしてください。</li></ul></blockquote><h3 id="手順-3-必要に応じて認証" tabindex="-1">手順 3：必要に応じて認証 <a class="header-anchor" href="#手順-3-必要に応じて認証" aria-label="Permalink to &quot;手順 3：必要に応じて認証&quot;">​</a></h3><ol><li>選択後に <strong>「下一步」</strong> をタップ</li><li>WeChat の案内に沿って認証を完了</li><li>しばらく待つ（数秒かかることがあります）</li></ol><blockquote><p>⚠️ 重要：</p><ul><li>エクスポート後、WeChat はメールまたは WeChat でファイルを送信します。</li><li>メール受け取りの場合は、WeChat 側でメールアドレス設定が必要です。</li></ul></blockquote><h3 id="手順-4-端末に保存" tabindex="-1">手順 4：端末に保存 <a class="header-anchor" href="#手順-4-端末に保存" aria-label="Permalink to &quot;手順 4：端末に保存&quot;">​</a></h3><ol><li>メール受け取りの場合： <ul><li>メールアプリで WeChat からのメールを開く</li><li>添付ファイル（CSV / Excel）をダウンロード</li><li>端末内（ファイルアプリで参照できる場所）に保存</li></ul></li><li>「ファイルに保存」できる場合： <ul><li>ダウンロードフォルダ等に保存</li><li>保存先を覚えておく</li></ul></li></ol><blockquote><p>📝 保存先の目安：</p><ul><li>iOS：ファイル App → ダウンロード</li><li>Android：ダウンロードフォルダ、または WeChat フォルダ</li></ul></blockquote><hr><h2 id="📱-手順-2-koala-にインポート" tabindex="-1">📱 手順 2：Koala にインポート <a class="header-anchor" href="#📱-手順-2-koala-にインポート" aria-label="Permalink to &quot;📱 手順 2：Koala にインポート&quot;">​</a></h2><h3 id="手順-1-インポート画面を開く" tabindex="-1">手順 1：インポート画面を開く <a class="header-anchor" href="#手順-1-インポート画面を開く" aria-label="Permalink to &quot;手順 1：インポート画面を開く&quot;">​</a></h3><ol><li>Koala を開く</li><li>画面下の <strong>「設定」</strong> をタップ</li><li><strong>「明細インポート」</strong> を探して開く</li></ol><h3 id="手順-2-インポート元を選択" tabindex="-1">手順 2：インポート元を選択 <a class="header-anchor" href="#手順-2-インポート元を選択" aria-label="Permalink to &quot;手順 2：インポート元を選択&quot;">​</a></h3><ol><li><strong>「インポート元」</strong> をタップ</li><li><strong>「WeChat」</strong> を選択</li></ol><blockquote><p>⚠️ 重要：必ず WeChat を選択してください。選択を間違えるとファイル形式を正しく解析できません。</p></blockquote><h3 id="手順-3-ファイルを選択" tabindex="-1">手順 3：ファイルを選択 <a class="header-anchor" href="#手順-3-ファイルを選択" aria-label="Permalink to &quot;手順 3：ファイルを選択&quot;">​</a></h3><ol><li><strong>「ファイルパス」</strong> をタップ</li><li>WeChat からエクスポートしたファイルを選択</li><li>ファイル名が表示されることを確認</li></ol><blockquote><p>📝 対応形式：</p><ul><li>CSV（<code>.csv</code>）</li><li>Excel（<code>.xlsx</code> / <code>.xls</code>）</li></ul></blockquote><h3 id="手順-4-帳本-ledger-を関連付け" tabindex="-1">手順 4：帳本（Ledger）を関連付け <a class="header-anchor" href="#手順-4-帳本-ledger-を関連付け" aria-label="Permalink to &quot;手順 4：帳本（Ledger）を関連付け&quot;">​</a></h3><ol><li><strong>「関連付け帳本」</strong> をタップ</li><li>取り込み先の帳本を選択</li></ol><blockquote><p>💡 ヒント：帳本が 1 つだけの場合、自動的に既定の帳本が選ばれることがあります。</p></blockquote><h3 id="手順-5-解析-→-プレビュー" tabindex="-1">手順 5：解析 → プレビュー <a class="header-anchor" href="#手順-5-解析-→-プレビュー" aria-label="Permalink to &quot;手順 5：解析 → プレビュー&quot;">​</a></h3><ol><li>右上の <strong>「解析」</strong> をタップ</li><li>解析が完了するとプレビュー画面へ移動</li></ol><blockquote><p>⚠️ 解析に失敗する場合：</p><ul><li>ファイル形式が正しいか</li><li>インポート元が WeChat になっているか</li><li>ファイルが破損していないか</li><li>WeChat から再度エクスポートして試してください</li></ul></blockquote><h3 id="手順-6-プレビュー・編集" tabindex="-1">手順 6：プレビュー・編集 <a class="header-anchor" href="#手順-6-プレビュー・編集" aria-label="Permalink to &quot;手順 6：プレビュー・編集&quot;">​</a></h3><p>プレビュー画面では以下ができます。</p><ul><li>日付ごとに明細を確認</li><li>1 件ずつ編集（カテゴリ、金額、時間、口座、タグ、メモなど）</li><li>長押しで無効な明細を削除</li><li>無効な明細をまとめてスキップ</li></ul><h3 id="手順-7-インポート実行" tabindex="-1">手順 7：インポート実行 <a class="header-anchor" href="#手順-7-インポート実行" aria-label="Permalink to &quot;手順 7：インポート実行&quot;">​</a></h3><ol><li>内容を確認したら <strong>「インポート」</strong> をタップ</li><li>完了まで待つ</li></ol><hr><h2 id="📋-wechat-明細ファイルの列-参考" tabindex="-1">📋 WeChat 明細ファイルの列（参考） <a class="header-anchor" href="#📋-wechat-明細ファイルの列-参考" aria-label="Permalink to &quot;📋 WeChat 明細ファイルの列（参考）&quot;">​</a></h2><p>WeChat の CSV は通常、次の列を含みます。</p><table tabindex="0"><thead><tr><th>列名（エクスポートの表記）</th><th>内容</th><th>例</th></tr></thead><tbody><tr><td>交易时间</td><td>取引日時</td><td>2024-01-01 12:00:00</td></tr><tr><td>交易类型</td><td>取引種別</td><td>微信红包 / 转账 / 消费等</td></tr><tr><td>交易对方</td><td>相手先</td><td>张三 / 商户名称</td></tr><tr><td>商品</td><td>内容</td><td>午餐 / 购物等</td></tr><tr><td>收/支</td><td>収入/支出</td><td>收入 / 支出</td></tr><tr><td>金额(元)</td><td>金額</td><td>100.00</td></tr><tr><td>支付方式</td><td>支払方法</td><td>零钱 / 银行卡</td></tr><tr><td>当前状态</td><td>状態</td><td>支付成功/已转账/已到账</td></tr><tr><td>交易单号</td><td>取引番号</td><td>4200001234567890</td></tr><tr><td>商户单号</td><td>店舗番号</td><td>1234567890</td></tr><tr><td>备注</td><td>メモ</td><td>备注内容</td></tr></tbody></table><p>Excel 版も列名と内容は同様で、ファイル形式が違うだけです。</p><hr><h2 id="⚠️-注意事項" tabindex="-1">⚠️ 注意事項 <a class="header-anchor" href="#⚠️-注意事項" aria-label="Permalink to &quot;⚠️ 注意事項&quot;">​</a></h2><h3 id="_1-ファイルの条件" tabindex="-1">1. ファイルの条件 <a class="header-anchor" href="#_1-ファイルの条件" aria-label="Permalink to &quot;1. ファイルの条件&quot;">​</a></h3><ul><li><strong>文字コード</strong>：UTF-8 推奨</li><li><strong>形式</strong>：CSV / Excel</li><li><strong>サイズ</strong>：1 ファイル 10MB 以下を推奨</li></ul><h3 id="_2-データの取り込み-概要" tabindex="-1">2. データの取り込み（概要） <a class="header-anchor" href="#_2-データの取り込み-概要" aria-label="Permalink to &quot;2. データの取り込み（概要）&quot;">​</a></h3><p>Koala は WeChat の列を自動で Koala の項目に変換します。</p><ul><li>取引日時 → 日付（文字列へ変換）</li><li>収入/支出 → 明細タイプ</li><li>金額 → 金額</li><li>支払方法 → 口座（名称で照合、存在しない場合は作成されることがあります）</li><li>相手先/状態/番号/メモ → メモとして結合</li></ul><h3 id="_3-カテゴリ・口座の確認" tabindex="-1">3. カテゴリ・口座の確認 <a class="header-anchor" href="#_3-カテゴリ・口座の確認" aria-label="Permalink to &quot;3. カテゴリ・口座の確認&quot;">​</a></h3><ul><li>自動マッチは完全ではないため、プレビュー画面で確認し必要なら修正してください。</li></ul><h3 id="_4-ファイルは編集しない" tabindex="-1">4. ファイルは編集しない <a class="header-anchor" href="#_4-ファイルは編集しない" aria-label="Permalink to &quot;4. ファイルは編集しない&quot;">​</a></h3><p>WeChat から書き出したファイルは、<strong>ヘッダー名の変更・列の削除・列の追加</strong> などをしないでください。解析に失敗する原因になります。</p><hr><h2 id="🔧-よくある質問" tabindex="-1">🔧 よくある質問 <a class="header-anchor" href="#🔧-よくある質問" aria-label="Permalink to &quot;🔧 よくある質問&quot;">​</a></h2><h3 id="q1-「下载账单」が見つかりません" tabindex="-1">Q1：「下载账单」が見つかりません <a class="header-anchor" href="#q1-「下载账单」が見つかりません" aria-label="Permalink to &quot;Q1：「下载账单」が見つかりません&quot;">​</a></h3><p>可能性：</p><ol><li>WeChat のバージョンが古い</li><li>入口が別の場所にある</li></ol><p>試すこと：</p><ul><li>明細画面の右上 <strong>「...」</strong> を確認</li><li>財布（钱包）から <strong>账单</strong> を探す</li><li>WeChat 検索で「账单导出」を検索</li></ul><h3 id="q2-メールが届きません" tabindex="-1">Q2：メールが届きません <a class="header-anchor" href="#q2-メールが届きません" aria-label="Permalink to &quot;Q2：メールが届きません&quot;">​</a></h3><p>確認：</p><ol><li>WeChat にメールアドレスを設定済みか</li><li>アドレスが正しいか</li><li>迷惑メールフォルダ</li><li>「ファイルに保存」方式を試す</li></ol><h3 id="q3-解析に失敗します" tabindex="-1">Q3：解析に失敗します <a class="header-anchor" href="#q3-解析に失敗します" aria-label="Permalink to &quot;Q3：解析に失敗します&quot;">​</a></h3><p>確認：</p><ol><li>CSV / Excel 形式か</li><li>インポート元が WeChat か</li><li>ファイルが破損していないか</li><li>文字コード（UTF-8 推奨）</li></ol><h3 id="q4-カテゴリが期待通りになりません" tabindex="-1">Q4：カテゴリが期待通りになりません <a class="header-anchor" href="#q4-カテゴリが期待通りになりません" aria-label="Permalink to &quot;Q4：カテゴリが期待通りになりません&quot;">​</a></h3><p>WeChat の分類と Koala の分類が一致しない場合があります。プレビュー画面で修正するか、インポート後にまとめて編集してください。</p><h3 id="q5-画像を取り込めますか" tabindex="-1">Q5：画像を取り込めますか？ <a class="header-anchor" href="#q5-画像を取り込めますか" aria-label="Permalink to &quot;Q5：画像を取り込めますか？&quot;">​</a></h3><p>現時点では対応していません。</p><h3 id="q6-どのくらいの期間を取り込めますか" tabindex="-1">Q6：どのくらいの期間を取り込めますか？ <a class="header-anchor" href="#q6-どのくらいの期間を取り込めますか" aria-label="Permalink to &quot;Q6：どのくらいの期間を取り込めますか？&quot;">​</a></h3><p>制限はありませんが、次を推奨します。</p><ol><li>1 回の取り込みは 3 か月程度まで</li><li>大量の場合はファイルを分割</li><li>インポート中はアプリを前面にしておく</li></ol><hr><h2 id="💡-使い方のコツ" tabindex="-1">💡 使い方のコツ <a class="header-anchor" href="#💡-使い方のコツ" aria-label="Permalink to &quot;💡 使い方のコツ&quot;">​</a></h2><ol><li>毎月など定期的に取り込むと管理しやすい</li><li>取り込み後にカテゴリを整理すると集計が見やすくなる</li><li>よく使う口座は先に作成しておくと、口座名が自動生成されにくい</li><li>念のため、取り込み前にバックアップを推奨</li></ol><hr><p><strong>最終更新</strong>：2026 年 5 月</p>',79)])])}const b=a(o,[["render",r]]);export{q as __pageData,b as default};
